package com.quran.learnedplayer.data

import android.content.Context
import org.json.JSONObject
import java.text.Normalizer

/**
 * Which translations, word-meaning languages, tafsirs and reciters exist, with their sources:
 * `assets/content_catalog.json`, generated by `.setup/make_content_catalog.py` and read by the web
 * app too (`web-app/static/js/core/catalog.js` holds the same rules; keep the two in step).
 *
 * Settings store an edition's stable [id], never its name, so a renamed edition or a new app
 * language changes nothing that was saved. Only Saheeh International and the English word
 * meanings are bundled; [ContentRepository] downloads anything else from Quran.com when chosen.
 */
data class ContentLanguage(val code: String, val name: String, val nativeName: String, val rtl: Boolean)

data class Edition(
    val id: String,
    val language: String,
    val name: String,
    val author: String,
    val source: String,
    val sourceUrl: String,
    val licence: String,
    /** Quran.com's resource id; null for a bundled edition. */
    val resourceId: Int?,
    val bundled: Boolean,
    val recommended: Boolean,
) {
    /** "Saheeh International · Tanzil.net", for credits. */
    val credit: String get() = "$name · $source"

    /** The name, and the author where the name doesn't already say who. */
    val label: String
        get() = if (author.isNotBlank() && author != name && !name.contains(author)) "$name — $author" else name
}

data class WordMeanings(val id: String, val language: String, val source: String, val bundled: Boolean)

/** How the Arabic is drawn: a bundled font for a script (`ui/theme/Type.kt` QuranFonts). */
data class MushafStyle(val id: String, val name: String, val author: String, val licence: String, val script: String)

data class CatalogReciter(val id: String, val name: String, val folder: String, val timingsAsset: String, val highlighting: Boolean)

/** How translations show beside the Arabic: the two existing switches, read as one choice. */
enum class TranslationStyle(val label: String, val description: String) {
    WORDS("Word meanings", "Under each Arabic word"),
    AYAH("Full translation", "The whole ayah, under the Arabic"),
    BOTH("Both", "Word meanings and the whole ayah"),
    ;

    val showWordTranslations: Boolean get() = this != AYAH
    val showAyahTranslation: Boolean get() = this != WORDS

    companion object {
        /** Neither switch on reads as words, the default. */
        fun of(showWordTranslations: Boolean, showAyahTranslation: Boolean): TranslationStyle = when {
            showWordTranslations && showAyahTranslation -> BOTH
            showAyahTranslation -> AYAH
            else -> WORDS
        }
    }
}

class ContentCatalog(
    val api: String,
    val defaultTranslation: String,
    val defaultWordMeanings: String,
    val defaultReciter: String,
    val languages: Map<String, ContentLanguage>,
    val translations: List<Edition>,
    val wordMeanings: List<WordMeanings>,
    val tafsirs: List<Edition>,
    val reciters: List<CatalogReciter>,
    val retired: Map<String, String>,
    val mushafStyles: List<MushafStyle> = emptyList(),
    val defaultMushafStyle: String = "uthmani-scheherazade",
) {
    fun mushafStyle(id: String?): MushafStyle? =
        mushafStyles.firstOrNull { it.id == id } ?: mushafStyles.firstOrNull { it.id == defaultMushafStyle }

    private fun follow(id: String?): String? {
        var current = id
        var steps = 0
        while (current != null && retired.containsKey(current) && steps++ < 8) current = retired[current]
        return current
    }

    /** The edition for a saved id: retired ids follow their replacement, unknown ones fall back. */
    fun translation(id: String?): Edition {
        val wanted = follow(id)
        return translations.firstOrNull { it.id == wanted } ?: translations.first { it.id == defaultTranslation }
    }

    /** The tafsir for a saved id; null for none, or one that no longer exists. */
    fun tafsir(id: String?): Edition? {
        if (id.isNullOrEmpty()) return null
        val wanted = follow(id)
        return tafsirs.firstOrNull { it.id == wanted }
    }

    fun wordMeanings(id: String?): WordMeanings =
        wordMeanings.firstOrNull { it.id == id } ?: wordMeanings.first { it.id == defaultWordMeanings }

    fun languageName(code: String, native: Boolean = false): String {
        val l = languages[code] ?: return code
        return if (native && l.nativeName.isNotBlank() && l.nativeName != l.name) "${l.nativeName} (${l.name})" else l.name
    }

    fun isRtl(code: String): Boolean = languages[code]?.rtl == true

    /** Languages with at least one translation, English first, then by English name. */
    fun translationLanguages(): List<String> =
        translations.map { it.language }.distinct()
            .sortedWith(compareBy<String> { it != "en" }.thenBy { languageName(it) })

    /** A language's translations: bundled, then recommended, then the rest, each by name. */
    fun translationsIn(code: String): List<Edition> =
        translations.filter { it.language == code }
            .sortedWith(compareBy<Edition> { !it.bundled }.thenBy { !it.recommended }.thenBy { it.name.lowercase() })

    /** Case- and accent-insensitive search over name, author and language. */
    fun search(query: String): List<Edition> {
        val q = fold(query).trim()
        if (q.isEmpty()) return translations
        return translations.filter { t ->
            listOf(t.name, t.author, t.language, languageName(t.language), languages[t.language]?.nativeName.orEmpty())
                .any { fold(it).contains(q) }
        }
    }

    /** Tafsirs, the reader's translation language first, then English. */
    fun tafsirsFor(preferLanguage: String): List<Edition> =
        tafsirs.sortedWith(
            compareBy<Edition> { it.language != preferLanguage }
                .thenBy { it.language != "en" }
                .thenBy { it.language }
                .thenBy { !it.recommended }
                .thenBy { it.name.lowercase() },
        )

    companion object {
        const val ASSET = "content_catalog.json"

        @Volatile private var loaded: ContentCatalog? = null

        /** The bundled catalog, parsed once per process. */
        fun get(context: Context): ContentCatalog =
            loaded ?: synchronized(this) {
                loaded ?: parse(context.applicationContext.assets.open(ASSET).bufferedReader().use { it.readText() })
                    .also { loaded = it }
            }

        fun parse(json: String): ContentCatalog {
            val root = JSONObject(json)
            require(root.optString("format") == "learned-ayahs-content-catalog") { "Not a content catalog" }
            val defaults = root.getJSONObject("defaults")
            val langs = root.getJSONObject("languages").let { o ->
                o.keys().asSequence().associateWith { code ->
                    val l = o.getJSONObject(code)
                    ContentLanguage(code, l.getString("name"), l.optString("nativeName", l.getString("name")), l.optBoolean("rtl"))
                }
            }
            fun editions(key: String): List<Edition> {
                val arr = root.getJSONArray(key)
                return List(arr.length()) { i ->
                    val e = arr.getJSONObject(i)
                    Edition(
                        id = e.getString("id"),
                        language = e.getString("language"),
                        name = e.getString("name"),
                        author = e.optString("author"),
                        source = e.optString("source"),
                        sourceUrl = e.optString("sourceUrl"),
                        licence = e.optString("licence"),
                        resourceId = if (e.has("resourceId")) e.getInt("resourceId") else null,
                        bundled = e.optBoolean("bundled"),
                        recommended = e.optBoolean("recommended"),
                    )
                }
            }
            val wbw = root.getJSONArray("wordMeanings").let { arr ->
                List(arr.length()) { i ->
                    val w = arr.getJSONObject(i)
                    WordMeanings(w.getString("id"), w.getString("language"), w.optString("source"), w.optBoolean("bundled"))
                }
            }
            val reciters = root.getJSONArray("reciters").let { arr ->
                List(arr.length()) { i ->
                    val r = arr.getJSONObject(i)
                    CatalogReciter(r.getString("id"), r.getString("name"), r.getString("folder"), r.getString("timingsAsset"), r.optBoolean("highlighting"))
                }
            }
            val styles = root.optJSONArray("mushafStyles")?.let { arr ->
                List(arr.length()) { i ->
                    val m = arr.getJSONObject(i)
                    MushafStyle(m.getString("id"), m.getString("name"), m.optString("author"), m.optString("licence"), m.optString("script"))
                }
            }.orEmpty()
            val retired = root.optJSONObject("retired")?.let { o -> o.keys().asSequence().associateWith { o.getString(it) } }.orEmpty()
            return ContentCatalog(
                api = root.getString("api"),
                defaultTranslation = defaults.getString("translation"),
                defaultWordMeanings = defaults.getString("wordMeanings"),
                defaultReciter = defaults.getString("reciter"),
                languages = langs,
                translations = editions("translations"),
                wordMeanings = wbw,
                tafsirs = editions("tafsirs"),
                reciters = reciters,
                retired = retired,
                mushafStyles = styles,
                defaultMushafStyle = defaults.optString("mushafStyle", "uthmani-scheherazade"),
            )
        }

        private fun fold(s: String): String =
            Normalizer.normalize(s, Normalizer.Form.NFD).replace(Regex("\\p{M}+"), "").lowercase()
    }
}

/** Provider text to plain text, and word meanings aligned to our text. Pure; see ContentCatalogTest. */
object ContentText {
    private val SUP = Regex("<sup\\b[^>]*>[\\s\\S]*?</sup>", RegexOption.IGNORE_CASE)
    private val BR = Regex("<br\\s*/?>", RegexOption.IGNORE_CASE)
    private val TAG = Regex("<[^>]*>")
    private val ENTITY = Regex("&(#x[0-9a-fA-F]+|#\\d+|[a-zA-Z]+\\d*);")
    private val SPACE_BEFORE_PUNCT = Regex("\\s+([,.;:!?،؛۔])")
    private val SPACES = Regex("\\s+")
    private val NAMED = mapOf("amp" to "&", "lt" to "<", "gt" to ">", "quot" to "\"", "apos" to "'", "nbsp" to " ")

    fun decodeEntities(s: String): String = ENTITY.replace(s) { m ->
        val e = m.groupValues[1]
        when {
            e.startsWith("#x") || e.startsWith("#X") -> e.substring(2).toIntOrNull(16)?.takeIf { it in 1..0x10FFFF }?.let { String(Character.toChars(it)) } ?: ""
            e.startsWith("#") -> e.substring(1).toIntOrNull()?.takeIf { it in 1..0x10FFFF }?.let { String(Character.toChars(it)) } ?: ""
            else -> NAMED[e.lowercase()] ?: m.value
        }
    }

    /**
     * A translation as plain text. Quran.com marks footnotes `<sup foot_note=N>1</sup>`; the
     * footnotes aren't fetched, so the marker goes rather than staying as a stray digit. Any
     * other markup is removed — this text is only ever shown as plain text.
     */
    fun plainTranslation(raw: String?): String {
        if (raw == null) return ""
        val stripped = TAG.replace(BR.replace(SUP.replace(raw, ""), " "), "")
        return SPACES.replace(SPACE_BEFORE_PUNCT.replace(decodeEntities(stripped), "$1"), " ").trim()
    }

    /** One word of a provider verse: its position, whether it's a word (not the end glyph), its meaning. */
    data class ProviderWord(val position: Int, val isWord: Boolean, val text: String?, val languageName: String?)

    /**
     * Meanings for our content words, matched by [positions] (our content words' positions). Our
     * text marks 2:181's number glyph as the end where Quran.com calls it a word, so matching is
     * by position, never by counting. Null where the provider has nothing in [languageName]; the
     * reader keeps the English meaning there.
     */
    fun alignWordMeanings(positions: List<Int>, words: List<ProviderWord>, languageName: String?): List<String?> {
        val theirs = words.filter { it.isWord }.associateBy { it.position }
        return positions.map { pos ->
            val w = theirs[pos] ?: return@map null
            val text = w.text?.takeIf { it.isNotBlank() } ?: return@map null
            if (languageName != null && w.languageName != null && !w.languageName.equals(languageName, ignoreCase = true)) return@map null
            plainTranslation(text).ifBlank { null }
        }
    }
}
